ART=ROOT/'docs/review/2026-09-25/donkeykong-character/audit-2026-10-08/art'
COMP=ROOT/'docs/review/2026-09-25/donkeykong-character/completion-2026-10-08'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def pin(p):return {'path':str(p.relative_to(ROOT)),'sha256':sha(p)}
def main():
    dest=ART/'grab-first-five-receiving-catch-grip-fit-plan-01.json'
    if dest.exists():raise ValueError('Preserve prior plan')
    specs=[('grab',8,7,'dk-grabpilot-batch01-attempt1-grab-native8-clean3',512,(785,525,1050,775),'HandL','HaveL'),('dash_grab',11,10,'dk-grabpilot-batch01-attempt1-dash_grab-native11-clean3',512,(825,532,1100,777),'HandL','HaveL'),('pivot_grab',12,11,'dk-grabpilot-batch02-attempt2-pivot_grab-native12-clean1',1024,(300,532,565,777),'HandR','HaveR'),('grab_pull',1,0,'dk-grabpilot-batch03-attempt1-grab_pull-native1-clean4',512,(900,460,1055,660),'HandL','HaveL'),('grab_hold',1,0,'dk-grabpilot-batch03-attempt1-grab_hold-native1-clean3',512,(755,505,925,685),'HandL','HaveL')]
    rows=[]
    for clip,sample,age,stem,rx,roi,hand,have in specs:
        target=ART/(stem+'-cutout.png');packed=ART/(stem+'-quarter.png');a=np.asarray(Image.open(target).convert('RGBA'))
        source=ART/'grab-source-socket-review-01'/f'{clip}-native{sample}-source-sockets.json';s=json.loads(source.read_text())
        x0,y0,x1,y1=roi;skin=(a[:,:,3]>=192)&(a[:,:,0]>170)&(a[:,:,1]>130)&(a[:,:,2]>65)&(a[:,:,0]>=a[:,:,1])&(a[:,:,1]>=a[:,:,2])
        region=np.zeros(skin.shape,bool);region[y0:y1,x0:x1]=skin[y0:y1,x0:x1]
        distance=distance_transform_edt(region);y,x=np.unravel_index(np.argmax(distance),distance.shape)
        assert region[y,x] and distance[y,x]>2
        rootpoint={'x':(float(x)+.5-rx)*5/26,'y':(float(y)+.5-832)*5/26}
        bodypoint={'x':rootpoint['x'],'y':rootpoint['y']+42}
        view=Image.new('RGBA',a.shape[1::-1],(25,30,39,255));view.alpha_composite(Image.fromarray(a));draw=ImageDraw.Draw(view)
        marks=[('target palm interior',(float(x)+.5,float(y)+.5),(40,255,100))]
        for bone,col in [(hand,(70,165,255)),(have,(255,205,70)),('Throw',(245,70,210))]:
            p=s['boneOriginProjectionActorWorld'][bone];marks.append((bone,(rx+p['x']*26/5,832+(p['y']-42)*26/5),col))
        for name,(px,py),col in marks:
            draw.ellipse((px-6,py-6,px+6,py+6),outline=col,width=3);draw.text((px+10,py-15),name,fill=col)
        ov=ART/f'{clip}-native{sample}-target-palm-source-priors-proposal.png';view.convert('RGB').save(ov)
        rows.append({'clip':clip,'nativeSample':sample,'selectedGameplayAge':age,'target':pin(target),'quarterTarget':pin(packed),'sourceSocketPacket':pin(source),'sourceGuide':pin(ART/'grab-first-five-native-guides-01'/f'{clip}-native{sample}.json'),'registration':{'fullRoot':[rx,832],'fullScaleToWorld':5/26,'quarterRoot':[rx/4,208],'quarterScaleToWorld':5/6.5,'bodyCentreFromRootY':-42},'gripProposal':{'state':'actual_target_pixel_seed_only_not_accepted_attachment_constraint','owner':hand.lower(),'sourcePriorBones':[hand,have,'Throw'],'roiExclusive':list(roi),'pixel':[int(x),int(y)],'RGBA':a[y,x].tolist(),'interiorSkinDistanceWorld':float(distance[y,x])*5/26,'rootRelativeAnchor':rootpoint,'actorCentreRelativeAnchor':bodypoint,'selection':'largest actual opaque cream interior in independently inspected active palm ROI; no receiving geometry used','overlay':pin(ov)},'sourceCatchProjections':s['sourceCatchProjections'],'nativeTransDeltaActorWorld':s['capturedTransDeltaActorWorld'],'wholeActionClockQualified':False,'receivingQualified':False,'catchQualified':False,'attachmentQualified':False})
    plan={'state':'review_ready_fitting_and_consumer_plan_only','targets':rows,'references':[pin(COMP/'mechanics/grab-recipient-arbitrary-compatibility-policy.json'),pin(COMP/'mechanics/grab-throw-next-batch-source-plan.json'),pin(COMP/'mechanics/grab-pull-hold-native-source-reconciliation.json'),pin(ART/'root-grab-first-four-corrected-target-static-review.json'),pin(ART/'root-pivot-grab-native12-attempt2-static-review.json')],
      'resourceOrder':['Root completes TS/test window and explicitly releases source-evaluation slot.','Export selected visible-mesh 15 major-region point clouds for these five exact native samples sequentially; exclude dominant Necktie cosmetics, retain neck/face and omitted-helper provenance. No raster required.','Apply each declared source guide support warp exactly; quarter target-alpha anatomical ownership seeded by cached source clouds, inspected hand/head/torso/finger separation and explicit cosmetic tie mask. Source points are priors, never acceptance bounds.','After ownership review, runtime compact target-constrained receiving fitter sequentially; anatomical 1-world margin, alpha32 floor .55, named classes, actual light/dark overlays/bothfaces. No automatic atlas install.','Independent source catch overlays and authored palm annotation review precede target-recipient anchor calibration; keep raw source and all rejected proposals.'],
      'receivingContract':{'existingField':'hurtboxPoses [{artFrameIndex,nativeSample,hurtboxes}]','existingConsumer':'donkeykongBodyPresentation getDonkeyKongBodyDrawing/selectDonkeyKongBodyReceiving','selection':'exact same frameWindows/artFrameIndex/drawing facing/root as sprite, frozen source age during hitlag','geometryScope':'authored target2D, not native hit_data or native3D parity; tie-only receiving excluded','pilotOnly':'one selected native sample per pilot; full clips require remaining active/clear/recovery samples and independent full action clocks'},
      'catchContract':{'proposedField':'catchCollisionPoses [{artFrameIndex,nativeSample,collisionHits:[{id,situation,capsule}]}]','currentConsumer':'Character.tickGrabCollider/spawnGrabHitbox in attacks.ts uses GrabSpec collisionHits; there is no paired catchCollisionPoses consumer yet','requiredConsumer':'runtime may implement geometry-only selected-drawing override before/after physics sensor updates, preserving source active windows, IDs0 ground/1 air, target status and no damage; clear retired sensors at selected source clear age','timing':{'grab':[7,10],'dash_grab':[10,13],'pivot_grab':[11,14]},'sourceScope':'top/root authored projection already matches source leaf scale5; raw Hand/Have origin overlap is a prior, not a native capture joint; Throw outside aerial projections is retained','pivotFacingRisk':'Character.ts entry sets actor facing to reversed rawMoveX while DK body candidate negates pivot p.facing. New source body already reaches backward. Resolve latched source/drawing/collision basis together and verify bothfaces; do not apply a second sign by assumption.'},
      'attachmentContract':{'proposedCaptorField':'victimAttachmentPoses [{artFrameIndex,nativeSample,captorAnchor,recipientContext,recipientFacingMultiplier}]','anchorConvention':'captorAnchor and recipientAnchor relative each independently registered physical foot/root, y down; supplied centre-relative coordinates are diagnostics only','proposedRecipientField':'per-context selected recipient pose supplies recipientAnchor, facing policy, alpha/receiving envelope and own frame/event clock','equation':'recipientFacing=recipientFacingMultiplier*captorDrawingFacing; recipientRoot=solvedCaptorRoot+(captorAnchor.x*captorDrawingFacing,captorAnchor.y)-(recipientAnchor.x*recipientFacing,recipientAnchor.y); recipientCentre=recipientRoot+its registered bodyCentreFromRoot','currentConsumer':'Character.applyInput fixed hitbox/cargo offsets plus conditional post-solver fixed pin; current offsets remain declared fallback until paired replacement accepted','requiredConsumer':'one coordinated post-solver follower before receiving contacts, keyed exact captureId+target bodyId/revision, independent of player order and actor reversal; frame/event clocks freeze together','gripSeedLimit':'palm interior proves target material ownership only. Grip contact location/orientation must be retargeted and reviewed against each recipient captured body; raw Throw/Have is never silently copied.'},
      'recipientCompatibility':{'small':'Pikachu reviewed captured/captured_hit high-hold art and separate own anchor; preserve existing PK floor envelope only ordinary context, never cargo by inheritance','large':'DK own capture_pulled_hi/capture_wait_hi/capture_damage_hi source and separately authored accepted target/anchor/receiving; Wolf/other supported bodies require their own accepted pose calibration, no DK Hip or PK anchor borrowed','DKAsRecipient':'PK and other grabber clocks remain legacy absent explicit opt-in; DK capture context derives captor state, not recipient ID alone','arbitrary':'unknown native hi/low/dx/girl/big selector is explicit gap; do not infer categories from body size/sex. Unsupported art/anchor is labeled fallback. Distinguish same-character actors by bodyId/capture revision.','cargo':'separate shoulder capture/event anchor, inherited entry tail native17/21/24, hold/walk/jump/fall and four ground/air throws; recipient separate entity/art; ordinary clearance and grip never reused automatically'},
      'clockAndStageGaps':['Pull native cancel2/resource extent20 does not establish current20-step pull threshold; common CatchPull/Wait status unavailable.','Hold source loop extent67/cancel0 does not establish source loop clock.','Pummel body contactage1/native2 and15 frozen callbacks remain independent of cooldown21.','Dash source Trans displacement +49.1285943985 world is separate from removed artroot; actual travel adapter and solved-root follower need evidence.','At sole source release sample solved socket once, detach before subsequent follower, ABS once. Entry facing independent from backthrow actor reversal.','Floor/wall/ceiling correction uses actual recipient alpha/receiving envelope; record anchor residual rather than teleport through solids or silently stretch art.'],
      'actualMatchMinimum':['DK->small PK and DK->large DK/Wolf standing/dash/pivot bothfaces, grounded/air recipient situation, catch hits and separated misses.','Actual sprite/receiving/catch/anchor overlay and same-step solved roots; independent small/large recipient anchor points, stage clearance residual.','Pull/hold/pummel, two-sided15freeze, cargo transition/tail/hold/walk/jump, all standard and cargo ground/air releases once.','DK as recipient of PK/other captor, reversed player iteration, same-ID regrab revision, floor/wall/ceiling feasibility, external hit/mash/KO/reset teardown.'],
      'canonicalWrites':False,'GPUUsed':False,'fitRun':False,'nativeEvaluationRun':False,'toolSha256':sha(Path(__file__))}
    dest.write_text(json.dumps(plan,indent=2)+'\n');print(json.dumps({'plan':str(dest.relative_to(ROOT)),'sha256':sha(dest),'points':[(r['clip'],r['gripProposal']['pixel']) for r in rows]}))
if __name__=='__main__':main()
